import{_ as e,c as t,o,a0 as i}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque.","frontmatter":{"title":"Building Pre-Shot Routines","description":"Develop a consistent pre-shot routine that anchors your focus, manages pressure, and creates the conditions for peak performance in pétanque."},"headers":[],"relativePath":"en/blog/pre-shot-routines.md","filePath":"en/blog/pre-shot-routines.md"}');const r=e({name:"en/blog/pre-shot-routines.md"},[["render",function(e,a,r,n,s,l){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="building-pre-shot-routines" tabindex="-1">Building Pre-Shot Routines <a class="header-anchor" href="#building-pre-shot-routines" aria-label="Permalink to &quot;Building Pre-Shot Routines&quot;">​</a></h1><p>The difference between a good throw and a great throw often happens before the boule leaves your hand. A well-designed pre-shot routine is your anchor in the storm of competition — a reliable sequence that prepares your mind and body for optimal performance.</p><h2 id="why-pre-shot-routines-matter" tabindex="-1">Why Pre-Shot Routines Matter <a class="header-anchor" href="#why-pre-shot-routines-matter" aria-label="Permalink to &quot;Why Pre-Shot Routines Matter&quot;">​</a></h2><p>Elite athletes across all sports use pre-shot routines. In pétanque, where each throw is discrete and pressure can build between shots, routines serve multiple purposes:</p><ul><li><strong>Consistency</strong>: Same preparation leads to more consistent execution</li><li><strong>Focus</strong>: Gives your mind a constructive task instead of worrying</li><li><strong>Transition</strong>: Helps you shift from thinking to doing</li><li><strong>Pressure management</strong>: Familiar actions calm the nervous system</li><li><strong>Reset</strong>: Clears the previous shot from your mind</li></ul><h2 id="anatomy-of-an-effective-routine" tabindex="-1">Anatomy of an Effective Routine <a class="header-anchor" href="#anatomy-of-an-effective-routine" aria-label="Permalink to &quot;Anatomy of an Effective Routine&quot;">​</a></h2><p>A good pre-shot routine has three phases:</p><h3 id="phase-1-assessment-5-10-seconds" tabindex="-1">Phase 1: Assessment (5-10 seconds) <a class="header-anchor" href="#phase-1-assessment-5-10-seconds" aria-label="Permalink to &quot;Phase 1: Assessment (5-10 seconds)&quot;">​</a></h3><ul><li>Read the terrain</li><li>Visualize the intended result</li><li>Choose your throw type</li><li>Commit to the decision</li></ul><h3 id="phase-2-preparation-5-10-seconds" tabindex="-1">Phase 2: Preparation (5-10 seconds) <a class="header-anchor" href="#phase-2-preparation-5-10-seconds" aria-label="Permalink to &quot;Phase 2: Preparation (5-10 seconds)&quot;">​</a></h3><ul><li>Take your position</li><li>Find your grip</li><li>Settle your breathing</li><li>Feel the weight of the boule</li></ul><h3 id="phase-3-execution-3-5-seconds" tabindex="-1">Phase 3: Execution (3-5 seconds) <a class="header-anchor" href="#phase-3-execution-3-5-seconds" aria-label="Permalink to &quot;Phase 3: Execution (3-5 seconds)&quot;">​</a></h3><ul><li>Final focus on target</li><li>Trust your body</li><li>Release without thought</li><li>Follow through naturally</li></ul><h2 id="building-your-personal-routine" tabindex="-1">Building Your Personal Routine <a class="header-anchor" href="#building-your-personal-routine" aria-label="Permalink to &quot;Building Your Personal Routine&quot;">​</a></h2><h3 id="step-1-observe-your-current-patterns" tabindex="-1">Step 1: Observe Your Current Patterns <a class="header-anchor" href="#step-1-observe-your-current-patterns" aria-label="Permalink to &quot;Step 1: Observe Your Current Patterns&quot;">​</a></h3><p>Before creating a new routine, notice what you already do:</p><ul><li>What do you do before successful throws?</li><li>What changes when you&#39;re under pressure?</li><li>What feels natural to you?</li></ul><h3 id="step-2-design-your-sequence" tabindex="-1">Step 2: Design Your Sequence <a class="header-anchor" href="#step-2-design-your-sequence" aria-label="Permalink to &quot;Step 2: Design Your Sequence&quot;">​</a></h3><p>Create a routine that includes:</p><p><strong>Physical elements:</strong></p><ul><li>How you approach the circle</li><li>How you pick up and hold the boule</li><li>Your stance and positioning</li><li>A specific breathing pattern</li></ul><p><strong>Mental elements:</strong></p><ul><li>A visualization of the result</li><li>A focus word or phrase</li><li>A commitment point (the moment you decide &quot;this is the throw&quot;)</li></ul><h3 id="step-3-keep-it-simple" tabindex="-1">Step 3: Keep It Simple <a class="header-anchor" href="#step-3-keep-it-simple" aria-label="Permalink to &quot;Step 3: Keep It Simple&quot;">​</a></h3><p>Your routine should be:</p><ul><li><strong>Short enough</strong> to maintain under pressure (15-25 seconds total)</li><li><strong>Simple enough</strong> to remember when stressed</li><li><strong>Flexible enough</strong> to adapt to different situations</li></ul><h2 id="example-routines" tabindex="-1">Example Routines <a class="header-anchor" href="#example-routines" aria-label="Permalink to &quot;Example Routines&quot;">​</a></h2><h3 id="the-pointer-s-routine" tabindex="-1">The Pointer&#39;s Routine <a class="header-anchor" href="#the-pointer-s-routine" aria-label="Permalink to &quot;The Pointer&#39;s Routine&quot;">​</a></h3><ol><li>Stand behind the circle, assess the terrain</li><li>Visualize the boule&#39;s path and landing spot</li><li>Step into the circle, find your stance</li><li>Three slow breaths while feeling the boule</li><li>Eyes on the target, release</li></ol><h3 id="the-shooter-s-routine" tabindex="-1">The Shooter&#39;s Routine <a class="header-anchor" href="#the-shooter-s-routine" aria-label="Permalink to &quot;The Shooter&#39;s Routine&quot;">​</a></h3><ol><li>Identify the target boule, choose the angle</li><li>Visualize the impact and result</li><li>Enter the circle with purpose</li><li>One deep breath, feel the weight</li><li>Lock eyes on target, execute</li></ol><h2 id="common-mistakes-to-avoid" tabindex="-1">Common Mistakes to Avoid <a class="header-anchor" href="#common-mistakes-to-avoid" aria-label="Permalink to &quot;Common Mistakes to Avoid&quot;">​</a></h2><h3 id="too-long" tabindex="-1">Too Long <a class="header-anchor" href="#too-long" aria-label="Permalink to &quot;Too Long&quot;">​</a></h3><p>If your routine takes more than 30 seconds, you&#39;re overthinking. Long routines give anxiety more time to build.</p><h3 id="too-rigid" tabindex="-1">Too Rigid <a class="header-anchor" href="#too-rigid" aria-label="Permalink to &quot;Too Rigid&quot;">​</a></h3><p>If any interruption destroys your routine, it&#39;s too fragile. Build in flexibility — if something breaks your concentration, have a reset trigger.</p><h3 id="skipping-under-pressure" tabindex="-1">Skipping Under Pressure <a class="header-anchor" href="#skipping-under-pressure" aria-label="Permalink to &quot;Skipping Under Pressure&quot;">​</a></h3><p>The routine matters most when pressure is highest. If you abandon it when stressed, you lose its protective benefits.</p><h3 id="focusing-on-mechanics" tabindex="-1">Focusing on Mechanics <a class="header-anchor" href="#focusing-on-mechanics" aria-label="Permalink to &quot;Focusing on Mechanics&quot;">​</a></h3><p>Your routine should end with focus on the result, not on technique. &quot;Hit the target&quot; not &quot;keep your elbow straight.&quot;</p><h2 id="practicing-your-routine" tabindex="-1">Practicing Your Routine <a class="header-anchor" href="#practicing-your-routine" aria-label="Permalink to &quot;Practicing Your Routine&quot;">​</a></h2><h3 id="in-training" tabindex="-1">In Training <a class="header-anchor" href="#in-training" aria-label="Permalink to &quot;In Training&quot;">​</a></h3><ul><li>Use your full routine for every throw, even casual ones</li><li>Time yourself to ensure consistency</li><li>Practice with distractions to build resilience</li></ul><h3 id="building-automaticity" tabindex="-1">Building Automaticity <a class="header-anchor" href="#building-automaticity" aria-label="Permalink to &quot;Building Automaticity&quot;">​</a></h3><p>The goal is for your routine to become automatic — something you do without thinking. This takes repetition:</p><ul><li>100+ throws with the same routine</li><li>Consistent use across different situations</li><li>Gradual exposure to pressure while maintaining the routine</li></ul><h2 id="adapting-to-competition" tabindex="-1">Adapting to Competition <a class="header-anchor" href="#adapting-to-competition" aria-label="Permalink to &quot;Adapting to Competition&quot;">​</a></h2><p>In matches, your routine may need slight adjustments:</p><ul><li><strong>Time pressure</strong>: Have a shortened version ready</li><li><strong>Weather conditions</strong>: Adjust physical elements as needed</li><li><strong>High pressure moments</strong>: Slow down slightly, don&#39;t speed up</li></ul><h2 id="the-reset-routine" tabindex="-1">The Reset Routine <a class="header-anchor" href="#the-reset-routine" aria-label="Permalink to &quot;The Reset Routine&quot;">​</a></h2><p>Equally important is what you do after a throw:</p><ol><li><strong>Accept the result</strong> — good or bad, it&#39;s done</li><li><strong>Physical reset</strong> — step back, shake out tension</li><li><strong>Mental reset</strong> — clear the throw from your mind</li><li><strong>Prepare for next</strong> — shift focus to what&#39;s coming</li></ol><hr><p><em>Related: <a href="/en/education/mental-strength/pre-shot-routine">Pre-Shot Routine Guide</a> | <a href="/en/education/mental-strength/handling-pressure">Handling Pressure</a> | <a href="/en/education/mindfulness/techniques">Mindfulness Techniques</a></em></p>',54)])])}]]);export{a as __pageData,r as default};
